<style scoped lang="scss" src="./fundraiser-banner-block.scss"></style>
<style lang="scss" src="./fundraiser-banner-block-sticky.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import Icon from "../icon/icon";
import Meter from "../meter/meter";
import Button from "../button/button";
import { MeterMode } from "../meter/meter.constants";
import { differenceInCalendarDays } from "date-fns";
import { IconShape } from "../icon/icon.constants";
import { CurrencyNotation, CurrencyNotationValues } from "../constants";
import { has } from "../../util/has";
import {
  destroyModalRootContent,
  ensureModalRoot,
} from "../../util/ensure-modal-root";
import { MountingPortal } from "portal-vue";
import { ButtonSize } from "../button/button.constants";
import MobileOnly from "../mobile-only/mobile-only";
import DesktopOnly from "../desktop-only/desktop-only";

/**
 * This a component to show information (days left, donation number and progress) of a fund
 * It also provides buttons to donate or become a fundraiser
 */
@Component({
  components: {
    Icon,
    Meter,
    Button,
    MountingPortal,
    MobileOnly,
    DesktopOnly,
  },
})
export default class FundraiserBannerBlock extends Vue {
  /**
   * This is primarily a feature for small pages that are on the body (IE story
   * book story). Set to true to prevent a sticky header bug from showing the
   * sticky header at the wrong time.
   */
  @Prop({ type: Object }) preventStickyHeaderBug;
  /** Current donation value */
  @Prop({ type: Number, default: 0 }) collected;
  /** Donation goal */
  @Prop({ type: Number, default: 1000 }) goal;
  /** Default image to show for the banner if no slot is provided */
  @Prop({ type: String, default: "" }) image;
  /** Total donation count given (Not total value) */
  @Prop({ type: Number, default: 0 }) donationNumber;
  /** The due date of the fundraiser */
  @Prop({ type: [Date, Number, String], default: () => new Date() }) dueDate;
  /** Indicates if days left indicator should be shown */
  @Prop({ type: Boolean, default: true }) showDaysLeft;
  /** Currency mode for this component */
  @Prop({
    type: String,
    default: CurrencyNotation.USD,
    validator: has(CurrencyNotationValues),
  })
  currency;
  /** Buttons to appear under the metrics in the banner */
  @Prop({ type: Array, default: () => [] }) buttons;
  /** Buttons to appear in the sticky header when you navigate beyond the banner */
  @Prop({ type: Array, default: () => [] }) headerButtons;
  /** Removes the sticky header when scrolling passed this component */
  @Prop({ type: Boolean }) disableStickyHeader;

  MeterMode = MeterMode;
  ButtonSize = ButtonSize;
  IconShape = IconShape;

  arrowColor = "#ffffff";
  arrowSize = 27.21;
  iconColor = "#2356f6";
  navBarMode = false;

  /**
   * This is the root modal element the nav bar mode resides in to render
   * floating above all the other elements in the DOM.
   */
  modalRoot = null;
  observer = null;

  get modalRootId() {
    return `#${this.modalRoot.id}`;
  }

  beforeMount() {
    // HACK: MountingPortal spawns mass duplicates. So as Thanos once said:
    //       Fine. I'll do it myself
    destroyModalRootContent("Menu");
    this.modalRoot = ensureModalRoot();
    if (!this.modalRoot) {
      console.warn("Could not establish modal root for floating componentry");
      return;
    }
  }

  mounted() {
    this.observer = new IntersectionObserver(this.handleIntersection, {
      rootMargin: "-150px 0px 0px 0px",
    });
    this.observer.observe(this.$refs.container);
  }

  beforeDestroy() {
    this.observer.disconnect();
  }

  get daysLeft() {
    let dueDate = this.dueDate;

    if (typeof dueDate === "number" || typeof dueDate === "string") {
      dueDate = new Date(this.dueDate);

      if (dueDate.toDateString() === "Invalid Date") {
        console.warn("Wrong date format");
      }
    }

    const diff = differenceInCalendarDays(dueDate, new Date());

    return diff < 0 ? 0 : diff;
  }

  handleClick(index) {
    /**
     * Fires when you click on a button. This fires the event with the index of
     * the button clicked which corresponds to the buttons prop.
     *
     * @event click {number}
     */
    this.$emit("click", index);
  }

  handleClickHeader(index) {
    /**
     * Fires when you click on a button. This fires the event with the index of
     * the button clicked which corresponds to the buttons prop.
     *
     * @event clickHeader {number}
     */
    this.$emit("clickHeader", index);
  }

  handleIntersection(entries) {
    const bodyCanScroll = this.preventStickyHeaderBug
      ? this.targetScrollElement
        ? this.targetScrollElement.scrollHeight >
          this.targetScrollElement.clientHeight
        : document.getElementsByTagName("body")[0].clientHeight >
          window.innerHeight
      : true;

    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        this.navBarMode = false;
      } else if (!this.disableStickyHeader && bodyCanScroll) {
        this.navBarMode = true;
      }
    });
  }

  /**
   * HACKY HACKS: Due to vue portal having it's own set of issues and we handle
   * its DOM disposal manually, this causes certain scenarios to throw errors
   * from the MountingPortal component. So, we just absorb those issues here for
   * now until better solutions can be discovered or Vue3 is used with better
   * native made portals.
   */
  errorCaptured(err, vm, info) {
    if (info === "beforeDestroy hook") {
      return false;
    }
  }
}
</script>

<template>
  <div class="FundraiserBannerBlock" ref="container">
    <DesktopOnly :media="900">
      <MountingPortal
        v-if="navBarMode && !disableStickyHeader"
        :mountTo="modalRootId"
        append
      >
        <div class="FundraiserBannerBlock__Sticky">
          <div class="FundraiserBannerBlock__Container">
            <div class="FundraiserBannerBlock__StickyLeft">
              <Meter
                :collected="collected"
                :goal="goal"
                :mode="MeterMode.MEDIUM_EMPHASIZED"
                :currency="currency"
              />
            </div>
            <div class="FundraiserBannerBlock__StickyRight">
              <div
                class="FundraiserBannerBlock__StickyButton"
                v-for="(button, i) in headerButtons"
                :key="i"
              >
                <Button
                  @click="handleClickHeader(i)"
                  :mode="button.mode"
                  :label="button.label"
                  :size="ButtonSize.LARGE"
                  :mobileSize="ButtonSize.LARGE"
                />
              </div>
            </div>
          </div>
        </div>
      </MountingPortal>
    </DesktopOnly>
    <MobileOnly :media="900">
      <MountingPortal v-if="!disableStickyHeader" :mountTo="modalRootId" append>
        <div class="FundraiserBannerBlock__Sticky">
          <div class="FundraiserBannerBlock__Container">
            <div class="FundraiserBannerBlock__StickyRight">
              <div
                class="FundraiserBannerBlock__StickyButton"
                v-for="(button, i) in headerButtons"
                :key="i"
              >
                <Button
                  @click="handleClickHeader(i)"
                  :mode="button.mode"
                  :label="button.label"
                  :size="ButtonSize.LARGE"
                  :mobileSize="ButtonSize.LARGE"
                />
              </div>
            </div>
          </div>
        </div>
      </MountingPortal>
    </MobileOnly>
    <div
      class="FundraiserBannerBlock__Left"
      v-bind:style="{ backgroundImage: `url(${image})` }"
    >
      <slot></slot>
    </div>
    <div class="FundraiserBannerBlock__Right">
      <div class="FundraiserBannerBlock__RightContent">
        <div class="FundraiserBannerBlock__Upper">
          <DesktopOnly :media="900">
            <Meter
              :collected="collected"
              :goal="goal"
              :mode="MeterMode.LARGE"
              :currency="currency"
            />
          </DesktopOnly>
          <MobileOnly :media="900">
            <Meter
              :collected="collected"
              :goal="goal"
              :mode="MeterMode.LARGE_MOBILE"
              :currency="currency"
            />
          </MobileOnly>
        </div>
        <div class="FundraiserBannerBlock__Middle">
          <div v-if="showDaysLeft" class="FundraiserBannerBlock__InfoBlock">
            <div class="FundraiserBannerBlock__InfoIcon">
              <Icon
                :shape="IconShape.CALENDAR_CHECK"
                :size="26"
                :color="iconColor"
              />
            </div>
            <div class="FundraiserBannerBlock__InfoRight">
              <div class="FundraiserBannerBlock__InfoTitle">Days left</div>
              <div class="FundraiserBannerBlock__InfoData">{{ daysLeft }}</div>
            </div>
          </div>
          <div class="FundraiserBannerBlock__InfoBlock">
            <div class="FundraiserBannerBlock__InfoIcon">
              <Icon
                :shape="IconShape.PIGGY_BANK"
                :size="26"
                :color="iconColor"
              />
            </div>
            <div class="FundraiserBannerBlock__InfoRight">
              <div class="FundraiserBannerBlock__InfoTitle">Donations</div>
              <div class="FundraiserBannerBlock__InfoData">
                {{ donationNumber }}
              </div>
            </div>
          </div>
        </div>
        <DesktopOnly>
          <div
            class="FundraiserBannerBlock__Button"
            v-for="(button, i) in buttons"
            :key="i"
          >
            <Button
              @click="handleClick(i)"
              :mode="button.mode"
              :label="button.label"
              :size="button.size"
            />
          </div>
        </DesktopOnly>
      </div>
    </div>
  </div>
</template>
